def block(kind: str, text: str):
    return {"type": kind, "text": text}

STRATEGY = {"システム戦略","システム企画","経営戦略マネジメント","技術戦略マネジメント","ビジネスインダストリ","企業活動","法務"}
MANAGEMENT = {"プロジェクトマネジメント","サービスマネジメント","システム監査"}

def major_area(fact):
    if fact[0] in MANAGEMENT: return "マネジメント"
    if fact[0] in STRATEGY: return "ストラテジ"
    return "テクノロジ"

def category_label(category):
    return f"{major_area((category,))}／{category}"

def build_fact_variants(fact, peers, ordinal):
    category, concept, correct, w1, w2, w3, why = fact
    wrongs = [w1, w2, w3]
    area_all = sorted([p for p in peers if major_area(p) == major_area(fact)], key=lambda x: (x[0], x[1]))
    same_category = sorted([p for p in area_all if p[0] == category], key=lambda x: x[1])
    target_pos = next(i for i,p in enumerate(area_all) if p[1] == concept)
    area_peers = [p for p in area_all if p[1] != concept]
    offset_rank = target_pos if target_pos < len(area_all)-1 else target_pos-1
    area_offset = (offset_rank * 7 + 11) % len(area_peers)
    area_order = [area_peers[(area_offset+i) % len(area_peers)] for i in range(len(area_peers))]

    # Reverse retrieval uses the narrowest useful distractor pool. When a
    # use two same-category distractors and one nearby same-area term. This
    # keeps the set plausible while preventing every item in a short category
    # from reusing the exact same four labels.
    category_pos = next(i for i,p in enumerate(same_category) if p[1] == concept)
    if len(same_category) >= 4:
        extras = [p for p in area_order if p[0] != category]
        label_peers = [same_category[(category_pos+i)%len(same_category)] for i in (1,2)] + [extras[category_pos%len(extras)]]
    else:
        label_peers = [area_peers[(target_pos+i)%len(area_peers)] for i in (1,2,3)]

    # Review choices contain one false pairing and three true definitions from
    # the closest available category. No target label in the stem gives away
    # which choice is wrong.
    compare_all = same_category if len(same_category) >= 4 else area_all
    compare_peers = [p for p in compare_all if p[1] != concept]
    compare_pos = next(i for i,p in enumerate(compare_all) if p[1] == concept)
    compare_rank = compare_pos if compare_pos < len(compare_all)-1 else compare_pos-1
    compare_offset = (compare_rank * 7 + 11) % len(compare_peers)
    comparison_peers = [compare_peers[(compare_offset+i) % len(compare_peers)] for i in range(3)]

    variants = []
    # 1) Direct definition: original, authored misconception options.
    variants.append(("definition", f"「{concept}」の説明として最も適切なものを選べ。", [correct,*wrongs], [why,*[f"誤り。{wrong}。正しくは、{why}" for wrong in wrongs]], why,
                     [f"「{concept}」の定義と各選択肢を照合する。", why, "似た用語の役割や適用条件を混同していないか確認する。"], concept))

    # 2) Reverse retrieval: identify the syllabus term from its defining property.
    term_options = [concept] + [p[1] for p in label_peers]
    term_explanations = [f"「{concept}」はこの特徴を持つ。{why}"] + [f"「{p[1]}」は対象・目的が異なる概念である。{p[6]}" for p in label_peers]
    variants.append(("term", f"次の説明に該当する用語を選べ。{correct}", term_options, term_explanations,
                     f"説明された性質は「{concept}」を指す。{why}", ["定義文の目的語と作用を拾う。", why, "似た用語は対象や目的の違いで区別する。"], concept))

    # 3) Error detection: one deliberately false concept-definition pairing
    # is mixed with three true, adjacent definitions. The concept name is only
    # in the choices, so matching the stem to a label cannot reveal the answer.
    false_pair=f"【{concept}】{w1}"
    comparison_options = [false_pair] + [f"【{p[1]}】{p[2]}" for p in comparison_peers]
    comparison_explanations = [f"この組合せは誤り。「{concept}」の正しい説明は「{correct}」。{why}"] + [f"これは「{p[1]}」の正しい説明なので、誤りを選ぶ設問の答えではない。{p[6]}" for p in comparison_peers]
    listed_terms="、".join([concept]+[p[1] for p in comparison_peers])
    review_stem=f"「{listed_terms}」の用語メモを点検する。次の記述のうち、用語と説明の組合せが誤っているものを選べ。"
    variants.append(("review", review_stem, comparison_options, comparison_explanations,
                     comparison_explanations[0], ["選択肢ごとに用語の対象と説明の役割を照合する。", comparison_explanations[0], "残る説明はそれぞれ該当用語に沿っていることを確かめる。"], concept))

    out=[]
    for angle, stem, options, choice_reasons, explanation, steps, concept_key in variants:
        out.append({"angle": angle, "area": major_area(fact), "category": category_label(category), "concept": concept_key,
                    "stem": stem, "choices": options, "choiceExplanations": choice_reasons,
                    "explanation": explanation, "steps": steps, "tags":[concept,angle], "concepts":[concept], "difficulty": 2 if angle == "term" else 3})
    return out

def materialize(raw, set_no, local_no, global_no):
    ci = global_no % 4
    options = raw["choices"][:]
    reasons = raw["choiceExplanations"][:]
    # Keep the correct option at a balanced position while preserving its
    # one-to-one explanation.
    base_correct = raw.get("correctIndex", 0)
    pairs = list(zip(options, reasons))
    correct_pair = pairs.pop(base_correct)
    pairs.insert(ci, correct_pair)
    options = [p[0] for p in pairs]
    reasons = [p[1] for p in pairs]
    stem=raw["stem"]
    return {"id":f"fe-practice-a-{set_no+1:02d}-q{local_no+1:02d}", "year":2026, "subject":"科目A",
      "category":raw["category"],"stem":stem,"choices":options,"correctIndex":ci,
      "explanation":raw["explanation"],"source":f"ピヨトレ！オリジナル 科目A 第{set_no+1}回 問{local_no+1}",
      "questionNumber":local_no+1,"difficulty":raw["difficulty"],"tags":raw["tags"],"concepts":raw["concepts"],
      "steps":raw["steps"],"administration":f"practice-a-{set_no+1:02d}","kind":"original","mockSetID":f"fe-practice-a-{set_no+1:02d}",
      "bodyBlocks":[block("text",stem)],"choiceExplanations":reasons,"explanationBlocks":[block("text",raw["explanation"])]}

def build_calculation(raw, global_no):
    category, concept, stem, correct, wrongs, why = raw
    options=[correct,*wrongs]
    return {"angle":"calculation","area":major_area((category,)),"category":category_label(category),"concept":concept,
      "stem":stem,"choices":options,"correctIndex":0,"choiceExplanations":[why]+[f"{wrong}はこの計算条件と一致しない。{why}" for wrong in wrongs],
      "explanation":why,"steps":["与えられた数量と単位を整理する。",why,"求めた値の単位と桁が条件に合うことを確かめる。"],
      "tags":[concept,"計算"],"concepts":[concept],"difficulty":3}

def main():
    rng = random.Random(9262026)
    tech=[f for f in FACTS if major_area(f)=="テクノロジ"]
    mgmt=[f for f in FACTS if major_area(f)=="マネジメント"]
    strat=[f for f in FACTS if major_area(f)=="ストラテジ"]
    assert len(tech)>=128 and len(mgmt)>=43 and len(strat)>=43
    # Select a balanced 214-objective core: 128 technology, 43 management,
    # 43 strategy. Unselected strategy records remain authored source material,
    # not synthetic repeats in the shipped question bank.
    for pool in (tech,mgmt,strat): rng.shuffle(pool)
    selected=tech[:128]+mgmt[:43]+strat[:43]
    rng.shuffle(selected)
    raw=[]
    for i,fact in enumerate(selected): raw.extend(build_fact_variants(fact, selected, i))
    raw.extend(build_calculation(c,i) for i,c in enumerate(CALCS))
    assert len(raw)==660
    buckets={"テクノロジ":[],"マネジメント":[],"ストラテジ":[]}
    for q in raw: buckets[q["area"]].append(q)
    for b in buckets.values(): rng.shuffle(b)
    sets=[]; questions=[]
    global_no=0
    # Exact per-mock distribution: 36 technology, 12 management, 12 strategy.
    for s in range(11):
        batch=buckets["テクノロジ"][s*36:(s+1)*36]+buckets["マネジメント"][s*12:(s+1)*12]+buckets["ストラテジ"][s*12:(s+1)*12]
        rng.shuffle(batch)
        ids=[]
        for local_no,item in enumerate(batch):
            q=materialize(item,s,local_no,global_no)
            questions.append(q); ids.append(q["id"]); global_no+=1
        sets.append({"id":f"fe-practice-a-{s+1:02d}","title":f"科目A オリジナル問題 第{s+1}回","kind":"original","questionIDs":ids,"questionCount":60,"minutes":90})
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps({"questions":questions,"mockSets":sets},ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    validate(questions, sets)
    print(f"wrote {len(questions)} questions, {len(sets)} mock sets -> {OUT}")

def validate(questions, sets):
    ids = [q["id"] for q in questions]
    assert len(questions) == 660 and len(set(ids)) == 660
    assert len(sets) == 11 and all(s["questionCount"] == len(s["questionIDs"]) == 60 for s in sets)
    assert len({q["stem"] for q in questions}) == len(questions)
    for q in questions:
        assert q["subject"] == "科目A" and len(q["choices"]) == len(q["choiceExplanations"]) == 4
        assert 0 <= q["correctIndex"] < 4 and q["choices"][q["correctIndex"]]
        assert all(q[k] for k in ("explanation","steps","concepts","bodyBlocks"))
        assert q["administration"] == q["mockSetID"].replace("fe-", "") and q["kind"] == "original"
    for s in sets:
        assert all(next(q for q in questions if q["id"] == qid)["mockSetID"] == s["id"] for qid in s["questionIDs"])
    positions = Counter(q["correctIndex"] for q in questions)
    assert max(positions.values()) - min(positions.values()) <= 1
    choice_signatures=Counter(tuple(sorted(" ".join(x.split()) for x in q["choices"])) for q in questions)
    assert len(choice_signatures)==len(questions), [x for x,n in choice_signatures.items() if n>1][:5]
    correct_texts=[q["choices"][q["correctIndex"]] for q in questions]
    assert len(set(correct_texts))==len(questions)
    for s in sets:
        qs=[q for q in questions if q["mockSetID"]==s["id"]]
        area_counts=Counter(q["category"].split("／")[0] for q in qs)
        assert area_counts=={"テクノロジ":36,"マネジメント":12,"ストラテジ":12}
    validate_calculations(questions)

def validate_calculations(questions):
    # Independent arithmetic oracles keyed by the emitted concept. Every
    # materialized calculation answer is compared with a separately evaluated
    # expression, rather than only checking a formula in the source tuple.
    expected={
      "CPU実行時間":f"{200_000_000*1.5/1_200_000_000:.2f}秒",
      "非圧縮画像容量":f"{1_600*1_200*24//8:,}バイト",
      "IPv4サブネットの利用可能ホスト数":f"{2**(32-26)-2}台",
      "損益分岐点売上高":f"{int(12_000_000/0.30/10_000):,}万円",
      "EVMのCPI":f"{600/750:g}",
      "PERT期待所要日数":f"{(2+4*5+14)/6:g}日",
      "直列システム稼働率":f"{0.9*0.8:g}",
      "確率加重期待値":f"{(0.7*100_000+0.3*(-40_000))/10_000:g}万円",
      "バックアップ転送時間":f"{int(90*1_000/30):,}秒",
      "伝送時間":f"{1_200*8/2_000_000*1_000:g}ミリ秒",
      "平均応答時間":f"{0.4+1.1:g}秒",
      "売上総利益率":f"{(8_000-5_200)/8_000*100:g}%",
      "アムダールの法則による高速化率":f"{1/((1-0.8)+0.8/4):g}倍",
      "RAID 1の実効容量":"2 TB",
      "伝送データ量の算出":f"{25*8/8:g} MB",
      "クリティカルパスの所要日数":f"{max(3,5)+4:g}日",
      "投資利益率":f"{120/800*100:g}%",
      "IPv4 /28の利用可能ホスト数":f"{2**(32-28)-2}台",
    }
    calc_questions=[q for q in questions if "計算" in q["tags"]]
    assert len(calc_questions)==len(expected)==18
    for q in calc_questions:
        concept=q["concepts"][0]
        assert q["choices"][q["correctIndex"]]==expected[concept], (concept,q["choices"][q["correctIndex"]],expected[concept])

